import heapq
from sys import stdin, stdout

def main():
    input = stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    m = int(data[index + 1])
    index += 2

    a = list(map(int, data[index:index + n]))
    index += n

    c = list(map(int, data[index:index + n]))
    index += n

    orders = []
    for _ in range(m):
        t = int(data[index]) - 1
        d = int(data[index + 1])
        index += 2
        orders.append((t, d))

    heap = []
    for i in range(n):
        if a[i] > 0:
            heapq.heappush(heap, (c[i], i))

    results = []
    for t, d in orders:
        cost = 0
        while d > 0:
            if heap:
                current_cost, current_type = heapq.heappop(heap)
                if a[current_type] > 0:
                    if a[current_type] >= d:
                        cost += d * current_cost
                        a[current_type] -= d
                        d = 0
                    else:
                        cost += a[current_type] * current_cost
                        d -= a[current_type]
                        a[current_type] = 0
                else:
                    heapq.heappush(heap, (current_cost, current_type))
            else:
                break

        if d == 0:
            results.append(cost)
        else:
            results.append(0)

    for result in results:
        stdout.write(str(result) + '\n')

if __name__ == "__main__":
    main()

